  "dtree.inst.tex": "\\begin{aligned}& V(\\text{C2}) = {pH}\\cdot{a} + {pL}\\cdot{b} = {vC2}\\\\ & V(\\text{C3}) = {pH}\\cdot{c} + {pL}\\cdot{d} = {vC3}\\\\ & V(\\text{D2}) = \\max({vC3};\\ {e}) = {vD2}\\\\ & V(\\text{C1}) = {pA}\\cdot{vC2} + {pR}\\cdot{vD2} = {vC1}\\\\ & V(\\text{D1}) = \\max({vC1};\\ {f}) = {vD1}\\end{aligned}",
  "dtree.inst.formula": "V(C2) = {pH}·{a} + {pL}·{b} = {vC2}\nV(C3) = {pH}·{c} + {pL}·{d} = {vC3}\nV(D2) = máx({vC3}; {e}) = {vD2}\nV(C1) = {pA}·{vC2} + {pR}·{vD2} = {vC1}\nV(D1) = máx({vC1}; {f}) = {vD1}",
